return {["fb15_01"]={["dsc"]=[[你走在一条青石大道上，人来人往非常繁忙，不时地有人骑着马匆匆而过。北面就是苏州城了。西南边远远望去，波光粼闪，白帆点缀，便是周遭五百里的太湖了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_01]],["name"]=[[青石官道]],["permission"]=2,["role1"]=[[fb15r01_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_02]]},["fb15_02"]={["down"]=[[fb15_01]],["dsc"]=[[这是苏州府的南城门。进进出出的吴侬软语，听来特让人舒服。门口的官兵开口喝骂，也是这种软绵声气。门上贴着一份告示。南北一条笔直的官道。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_02]],["name"]=[[南门]],["permission"]=2,["role1"]=[[fb15r02_1]],["role2"]=[[fb15r02_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_03]]},["fb15_03"]={["down"]=[[fb15_02]],["dsc"]=[[你走在一条繁华的街道上，向南北两头延伸。北边通往城南大街的中心地段，东面是听雨轩，西面是留园，望南面，是苏州城的南城门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_03]],["item1"]=[[fubentiaozhuan2]],["left"]=[[fb15_04]],["leftDown"]=[[fb15_139]],["name"]=[[南大街]],["permission"]=2,["right"]=[[fb15_08]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_10]]},["fb15_04"]={["dsc"]=[[留园是苏州的一大名景之一，它以结构布局紧密、厅堂华丽宏敝、装饰精美典雅而享有“吴中第一名园”之誉。]],["id"]=[[fb15_04]],["left"]=[[fb15_05]],["name"]=[[留园]],["permission"]=2,["right"]=[[fb15_03]],["role1"]=[[fb15r04_1]],["role2"]=[[fb15r04_2]],["role3"]=[[fb15r04_3]],["stepMusic"]=[[jiaobu]]},["fb15_05"]={["dsc"]=[[荷花厅的主建筑面阔三间，宽敝高爽，厅名取朱熹:“一水方涵碧，千林以变红”之诗意。厅前宽广的平台依临荷池，为夏日赏荷纳凉胜处，故称“荷花厅”。厅后有花台庭院，叠石种树，自成一景。]],["id"]=[[fb15_05]],["item1"]=[[bfitem1]],["left"]=[[fb15_06]],["name"]=[[荷花厅]],["permission"]=2,["right"]=[[fb15_04]],["role1"]=[[fb15r05_1]],["stepMusic"]=[[jiaobu]]},["fb15_06"]={["dsc"]=[[古木交柯在荷花厅的西面，一排不同图案的漏窗，使你透过漏窗隐隐看到中部的水光山色和高低错落的楼阁，此处赏景，有“移步换景”之妙。向西窗孔可以遥望绿荫轩、明瑟楼，给人一种“庭院深深深几许”和空间不尽之感。]],["id"]=[[fb15_06]],["item1"]=[[bfitem2]],["leftDown"]=[[fb15_07]],["name"]=[[古木交柯]],["permission"]=2,["right"]=[[fb15_05]],["stepMusic"]=[[jiaobu]]},["fb15_07"]={["dsc"]=[[一池池水映入你的眼帘，小蓬莱翼然水中，曲折的石桥上架着紫藤花棚。池东你可以看到曲溪楼、西楼、清风池等小筑，掩映于花木山石之间。池西的山腰间，桂树丛生。阵阵桂香，沁人心脾。轩下，水涧两岸叠石重重，你不禁为此景而赞叹不已。]],["id"]=[[fb15_07]],["name"]=[[池塘]],["permission"]=2,["rightUp"]=[[fb15_06]],["stepMusic"]=[[jiaobu]]},["fb15_08"]={["dsc"]=[[听雨轩是苏州城内的一处唯一的一家书店了。这里有着各种各样的书籍，什么小说啦、风光旅游啦、手艺制作啦、基本武功啦，等等等等。只须花几两银子就可买到你想要的书。]],["id"]=[[fb15_08]],["left"]=[[fb15_03]],["name"]=[[听雨轩]],["permission"]=2,["role1"]=[[fb15r08_1]],["role2"]=[[fb15r08_2]],["stepMusic"]=[[jiaobu]]},["fb15_09"]={["dsc"]=[[这是一家老字号的钱庄，已有几百年的历史，在全国各地都有分店。它发行的银票信誉非常好，通行全国。在对面的墙上挂了块牌子。]],["id"]=[[fb15_09]],["name"]=[[聚宝斋]],["permission"]=2,["right"]=[[fb15_10]],["role1"]=[[fb15r09_1]],["stepMusic"]=[[jiaobu]]},["fb15_10"]={["down"]=[[fb15_03]],["dsc"]=[[南大街乃是城里的繁华地段，一到晚上，一派灯红酒绿，尤为热闹。笑声、歌声、琴声、箫声，汇成一片送入了你的耳朵，你不禁心猿意马，很想就此停步享受一番。从这里看去，苏州南城的街景是一片喧闹。在街的东北面是一个茶馆，正东望去是一座苏州园林。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_10]],["left"]=[[fb15_09]],["leftDown"]=[[fb15_11]],["name"]=[[南大街]],["permission"]=1,["right"]=[[fb15_13]],["rightUp"]=[[fb15_12]],["role1"]=[[fb15r10_1]],["role2"]=[[QXr10_1]],["role3"]=[[QXr10_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_19]]},["fb15_100"]={["dsc"]=[[走廊转角处开的一个小厅，一张石凳摆放在一旁供人休息。]],["id"]=[[fb15_100]],["left"]=[[fb15_99]],["name"]=[[廊厅]],["permission"]=2,["right"]=[[fb15_101]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_101"]={["down"]=[[fb15_104]],["dsc"]=[[完全荒废的花园。枯枝杂草胡乱生长着。一棵槐树下结着一把秋千，正在随风晃动。]],["id"]=[[fb15_101]],["item1"]=[[fb15item44]],["left"]=[[fb15_100]],["name"]=[[废弃花园]],["permission"]=2,["right"]=[[fb15_102]],["role1"]=[[msnpc1]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_97]]},["fb15_102"]={["dsc"]=[[走廊的尽头是死路，墙壁被封死了有一处墙壁的颜色有些发白，比旁边的墙壁要新一些，似乎是后来刷上的。]],["id"]=[[fb15_102]],["item1"]=[[fb15item65]],["left"]=[[fb15_101]],["name"]=[[走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_103"]={["dsc"]=[[墙壁后是一段走廊，直通地下，里面光线十分晦暗，一股霉变的气味扑鼻而来。墙角倒着一具尸体，眼睛完全烂去，空洞的眼眶朝着地窖的入口方向。尸体旁边有一个小瓷瓶和一把铜钥匙。]],["id"]=[[fb15_103]],["item1"]=[[fb15item45]],["item2"]=[[fb15item46]],["item3"]=[[fb15item67]],["item4"]=[[fb15item83]],["left"]=[[fb15_102]],["name"]=[[地窖]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_104"]={["down"]=[[fb15_106]],["dsc"]=[[完全荒废的花园。枯枝杂草胡乱生长着。]],["id"]=[[fb15_104]],["item1"]=[[fb15item81]],["name"]=[[废弃花园]],["permission"]=2,["right"]=[[fb15_105]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_101]]},["fb15_105"]={["dsc"]=[[大门旁边的门房，放着桌椅。桌子上砚台里的墨迹干的龟裂开来。毛笔上结满蛛网。]],["id"]=[[fb15_105]],["item1"]=[[fb15item48]],["item2"]=[[fb15item49]],["left"]=[[fb15_104]],["name"]=[[阴影房门]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_106"]={["down"]=[[fb15_107]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_106]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_104]]},["fb15_107"]={["down"]=[[fb15_108]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_107]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_106]]},["fb15_108"]={["down"]=[[fb15_109]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_108]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_107]]},["fb15_109"]={["down"]=[[fb15_110]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_109]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_108]]},["fb15_11"]={["dsc"]=[[这里是书院的讲堂，窗明几净，一尘不染。一位老夫子坐在太师椅上讲学。在他的两侧坐满了求学的学生。一张古意盎然的书案放在他的前面，案上摆着几本翻开了的线装书籍。]],["id"]=[[fb15_11]],["name"]=[[书院]],["permission"]=2,["rightUp"]=[[fb15_10]],["role1"]=[[fb15r11_1]],["role2"]=[[fb15r11_2]],["role3"]=[[bfr11_1]],["stepMusic"]=[[jiaobu]]},["fb15_110"]={["down"]=[[fb15_111]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_110]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_109]]},["fb15_111"]={["down"]=[[fb15_130]],["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_111]],["name"]=[[潮湿走廊]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_110]]},["fb15_112"]={["dsc"]=[[这扇门已经腐朽的不成样子，轻轻一推便碎了一地。门上的铜环泛着绿色，贴在两旁的门联字迹模糊，已经无法辨认。]],["id"]=[[fb15_112]],["item1"]=[[fb15item50]],["leftDown"]=[[fb15_113]],["name"]=[[腐朽大门]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_113"]={["dsc"]=[[一条杂草丛生的荒路，杂草长到了膝盖高。四周没有一个行人，看来已经荒废很久了。]],["id"]=[[fb15_113]],["leftDown"]=[[fb15_114]],["name"]=[[荒路]],["permission"]=2,["rightUp"]=[[fb15_112]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_114"]={["dsc"]=[[一条杂草丛生的荒路，杂草长到了膝盖高。四周没有一个行人，看来已经荒废很久了。]],["id"]=[[fb15_114]],["leftDown"]=[[fb15_40]],["name"]=[[荒路]],["permission"]=2,["rightUp"]=[[fb15_113]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_115"]={["down"]=[[fb15_112]],["dsc"]=[[这条小路四周荒无人烟，杂草蔓延，风声过处，处处呜咽不断，仔细听时却又消失不见。]],["id"]=[[fb15_115]],["name"]=[[阴森小路]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_116]]},["fb15_116"]={["down"]=[[fb15_115]],["dsc"]=[[这条小路四周荒无人烟，杂草蔓延，风声过处，处处呜咽不断，仔细听时却又消失不见。]],["id"]=[[fb15_116]],["name"]=[[阴森小路]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_117]]},["fb15_117"]={["down"]=[[fb15_116]],["dsc"]=[[这条小路四周荒无人烟，杂草蔓延，风声过处，处处呜咽不断，仔细听时却又消失不见。]],["id"]=[[fb15_117]],["name"]=[[阴森小路]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_118]]},["fb15_118"]={["down"]=[[fb15_117]],["dsc"]=[[这条小路四周荒无人烟，杂草蔓延，风声过处，处处呜咽不断，仔细听时却又消失不见。]],["id"]=[[fb15_118]],["name"]=[[阴森小路]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_120]]},["fb15_119"]={["dsc"]=[[此处全是坟墓，渡鸦成群结队盘旋不走，四周阴风怒号，让人不寒而栗。]],["id"]=[[fb15_119]],["name"]=[[乱坟岗]],["permission"]=2,["right"]=[[fb15_120]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_12"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人，或高声谈笑，或交头接耳。几个店伙计在一旁伺候着客人们，在台后坐着一位老板娘，正在弹着算盘。]],["id"]=[[fb15_12]],["item1"]=[[fb15r12_101]],["item2"]=[[MHQXr12_1]],["item3"]=[[MHQXr12_2]],["leftDown"]=[[fb15_10]],["name"]=[[茶