m1"]=[[wabaorenwu18]],["name"]=[[无名洞窟]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_136"]={["down"]=[[fb15_53]],["dsc"]=[[这是春在楼的二楼，装饰与一楼截然不同。只见走廊被分隔成各个雅间，上面挂着小木牌，是每个雅间的名字。相比起一楼，二楼价格高昂，只有头有脸，或者富有的人才会选择来二楼饮酒作乐。]],["id"]=[[fb15_136]],["item1"]=[[fb15item328]],["item2"]=[[cg2item1]],["item3"]=[[addsangenpc]],["name"]=[[雅间]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_137"]={["down"]=[[fb15_74]],["dsc"]=[[这里是寒山寺的后寺，一颗奇大无比的祈福树矗立于此，上面挂满了祈福条，周遭满是祈福的人群，旁边还有一位老僧微笑不语。]],["id"]=[[fb15_137]],["item1"]=[[wabaorenwu25]],["item2"]=[[2qibfrwnpclj]],["name"]=[[后寺]],["permission"]=2,["role1"]=[[fb15r137_1]],["role2"]=[[fb15r137_2]],["role3"]=[[fb15r137_3]],["role4"]=[[fb15r137_4]],["stepMusic"]=[[jiaobu]]},["fb15_138"]={["id"]=[[fb15_138]],["item1"]=[[fubentiaozhuan5]],["name"]=[[苏州北大街]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_139"]={["id"]=[[fb15_139]],["item1"]=[[fubentiaozhuan6]],["name"]=[[苏州南大街]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_14"]={["dsc"]=[[这里曾是为园主接待宾客和亲友的地方，有时也作为演戏说书或写诗做画之处。轩名取朱熹“前揖庐山，一峰独绣”和高启的“笑指庭前柏”句诗意。轩内摆设古香古色。凭轩眺望，满目石峰嶙峋，古柏虬枝盘绕，旧有桃源“十八景”之称。]],["id"]=[[fb15_14]],["leftDown"]=[[fb15_13]],["name"]=[[揖峰指柏轩]],["permission"]=2,["role1"]=[[fb15r14_1]],["stepMusic"]=[[jiaobu]]},["fb15_140"]={["id"]=[[fb15_140]],["item1"]=[[fubentiaozhuan7]],["name"]=[[苏州西大街]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_141"]={["id"]=[[fb15_141]],["item1"]=[[fubentiaozhuan8]],["name"]=[[苏州东大街]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_142"]={["id"]=[[fb15_142]],["item1"]=[[szjcsm]],["name"]=[[凌府]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_15"]={["dsc"]=[[燕誉堂是全园主厅，旧时系园主宴客处。曾经作为御膳房。堂名取于《诗经》:“式燕且誉，好而无射”。此处建筑为鸳鸯厅形状，高敞宏丽，堂内陈设富丽精致。]],["id"]=[[fb15_15]],["left"]=[[fb15_13]],["name"]=[[燕誉堂]],["permission"]=1,["rightDown"]=[[fb15_16]],["role1"]=[[fb15r15_1]],["stepMusic"]=[[jiaobu]]},["fb15_16"]={["dsc"]=[[亭内高高悬挂御笔题写的“真趣”匾一块。亭内装饰精致金碧辉煌。梁架、围屏、裙板上雕刻的人物、花鸟图案惟妙惟肖。在此可以环览全园景色。]],["id"]=[[fb15_16]],["leftUp"]=[[fb15_15]],["name"]=[[真趣亭]],["permission"]=1,["right"]=[[fb15_17]],["role1"]=[[fb15r16_1]],["role2"]=[[fb15r16_2]],["stepMusic"]=[[jiaobu]]},["fb15_17"]={["down"]=[[fb15_18]],["dsc"]=[[阁内的桌凳、花窗、地坪、书画皆取材于梅花，并悬匾额“绮窗春讯”。阁前种植了许多枝梅，以符阁名。曾为旧时文人著书、绘画之处。]],["id"]=[[fb15_17]],["left"]=[[fb15_16]],["name"]=[[问梅阁]],["permission"]=1,["role1"]=[[fb15r17_1]],["stepMusic"]=[[jiaobu]]},["fb15_18"]={["dsc"]=[[立雪堂名自“程门立雪”和“断臂立雪”之典。堂前小院中的湖石、形似牛、蟹、狮、蛙，谓“狮子静观牛吃蟹”，颇生动有趣。]],["id"]=[[fb15_18]],["name"]=[[立雪堂]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb15_17]]},["fb15_19"]={["down"]=[[fb15_10]],["dsc"]=[[宝带桥横跨于苏州的运河之上，又因桥形宛若长带，被称为长桥。桥面宽阔，行人在桥上来往，桥边有城里的小贩吆喝、叫卖着，熙熙攘攘，热闹非凡。宝带桥卧于碧波之上，相应生辉，分外多娇。这里是中秋赏月的一处绝佳之地。]],["id"]=[[fb15_19]],["item1"]=[[QXr19_2]],["item2"]=[[ever19_1]],["item3"]=[[fb15item303]],["leftUp"]=[[fb15_20]],["name"]=[[宝带桥]],["permission"]=1,["rightUp"]=[[fb15_36a]],["role1"]=[[fb15r19_1]],["role2"]=[[fb15r19_3]],["role3"]=[[fb15r19_100]],["role4"]=[[QXr19_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_35]]},["fb15_20"]={["down"]=[[fb15_24]],["dsc"]=[[这是一条宽阔的青石板街道，向东西两头延伸。西大街是衙门所在，行人稀少，静悄悄地很是冷清。东边是沧浪亭和宝带桥，南边是兵营。北边就是衙门了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_20]],["left"]=[[fb15_25]],["leftUp"]=[[fb15_22]],["name"]=[[西大街]],["permission"]=2,["rightDown"]=[[fb15_19]],["rightUp"]=[[fb15_35]],["role1"]=[[fb15r20_1]],["role2"]=[[fb15r20_2]],["role3"]=[[fb15r20_100]],["role4"]=[[fb15r20_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_21]]},["fb15_21"]={["down"]=[[fb15_20]],["dsc"]=[[堂上东西有两根楹柱，挂着一幅对联，但是你根本无心细看。正墙上悬挂一个横匾，上面横书“正大光明”四个金光闪闪的大字。“肃静”“回避”的牌子分列两侧。知府正坐在文案后批阅文书，师爷随侍在后。]],["id"]=[[fb15_21]],["item1"]=[[fb15r21_100]],["item2"]=[[fb15r21_101]],["item3"]=[[suzhou003]],["name"]=[[衙门]],["permission"]=2,["role1"]=[[fb15r21_1]],["role2"]=[[fb15r21_2]],["role3"]=[[fb15r21_3]],["role4"]=[[fb15r21_5]],["stepMusic"]=[[jiaobu]]},["fb15_22"]={["dsc"]=[[这里是码头。它是朝廷漕运要塞，水陆必经之处。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_22]],["item1"]=[[fb15r22_102]],["item2"]=[[fb15item304]],["item3"]=[[2019qxhdd1]],["leftUp"]=[[fb15_23]],["name"]=[[码头]],["permission"]=2,["rightDown"]=[[fb15_20]],["role1"]=[[duanwujie]],["role2"]=[[duanwujie1]],["role3"]=[[fb15r22_100]],["role4"]=[[fb15r22_101]],["stepMusic"]=[[jiaobu]]},["fb15_23"]={["dsc"]=[[这里是太湖边的隐居人士，一切都只是个迷啊。]],["id"]=[[fb15_23]],["name"]=[[水云间]],["permission"]=2,["rightDown"]=[[fb15_22]],["role1"]=[[fb15r22_1]],["stepMusic"]=[[jiaobu]]},["fb15_24"]={["dsc"]=[[这里是兵营，密密麻麻到处都是官兵，有的在武将的指挥下列队操练，有的独自在练功，有的坐着、躺着正在休息。南墙下坐着主帅，不动声色地寻视着四周。看到你进来，他们全都向你包围了过来，形势看来不太妙。]],["id"]=[[fb15_24]],["name"]=[[兵营]],["permission"]=2,["role1"]=[[fb15r24_1]],["role2"]=[[fb15r24_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_20]]},["fb15_25"]={["down"]=[[fb15_140]],["dsc"]=[[你走在西大街上，感到这里的街面要比别处的干净、整洁。大概因为靠近衙门、兵营可受保护的缘故，富人们都喜欢住在这里。东边静悄悄地没有几个行人，西边是西城门通往郊外。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_25]],["item1"]=[[fubentiaozhuan3]],["left"]=[[fb15_28]],["name"]=[[西大街]],["permission"]=2,["right"]=[[fb15_20]],["role1"]=[[fb15r25_1]],["role2"]=[[fb15r25_2]],["role3"]=[[mpqzrwnpc01a]],["stepMusic"]=[[jiaobu]]},["fb15_26"]={["down"]=[[fb15_28]],["dsc"]=[[你走进书场，看见里面热热闹闹的，场子里都是听书的，场子前面有一位说书先生，他看上去四五十岁，手中拿着一块响板，正在聚精会神地说着评书--《杨家将》。你也逐渐被评书的内容所吸引，场中的人们不时的发出惊叹和喝彩声，时不时将铜板抛了上去。]],["id"]=[[fb15_26]],["name"]=[[书场]],["permission"]=2,["role1"]=[[fb15r26_1]],["role2"]=[[fb15r26_2]],["role3"]=[[mkzmnpc]],["stepMusic"]=[[jiaobu]]},["fb15_27"]={["dsc"]=[[你一走进玄妙观，看到观中香火缭绕，香客众多。殿是重檐歇山式，屋脊高十几米，内有高大殿柱四十根。屋面坡度平缓，出檐较深，斗拱疏朗宏大，殿内正中有砖砌须弥座，座上供奉着的三尊高十几米的泥塑三清金身像，法像庄严，神采奕奕，不失为道教雕塑中的精品。]],["id"]=[[fb15_27]],["item1"]=[[fb15item10]],["item2"]=[[lylitem1]],["name"]=[[玄妙观]],["permission"]=2,["role1"]=[[fb15r27_1]],["role2"]=[[fb15r27_2]],["role3"]=[[fb15r27_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_28]]},["fb15_28"]={["down"]=[[fb15_27]],["dsc"]=[[这是号称天堂的苏州西城门，城门正上方刻着“西门”两个楷书大字，城墙上贴着几张官府告示。西门外通向寒山寺一条笔直的青石板大道向东西两边延伸，南边是玄妙观，北边是一个书场。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_28]],["item1"]=[[fb15item324]],["left"]=[[fb15_29]],["name"]=[[西门]],["permission"]=2,["right"]=[[fb15_25]],["role1"]=[[fb15r28_1]],["role2"]=[[fb15r28_100]],["role3"]=[[fb15r28_101]],["role4"]=[[fb15r28_102]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_26]]},["fb15_29"]={["dsc"]=[[你走在一条青石大道上，人来人往非常繁忙，不时地有人骑着马匆匆而过。大道两旁有一些小货摊，似乎是一处集市。东面就是苏州城了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_29]],["left"]=[[fb15_30]],["name"]=[[青石官道]],["permission"]=2,["right"]=[[fb15_28]],["role1"]=[[fb15r29_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_128]]},["fb15_30"]={["dsc"]=[[你走在一条青石大道上，人来人往非常繁忙，不时地有人骑着马匆匆而过。大道两旁有一些小货摊，似乎是一处集市。东面就是苏州城了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_30]],["item1"]=[[fb15item307]],["left"]=[[fb15_31]],["name"]=[[青石官道]],["permission"]=2,["right"]=[[fb15_29]],["role1"]=[[fb15r30_100]],["role2"]=[[fb15r30_101]],["role3"]=[[fb15r30_102]],["stepMusic"]=[[jiaobu]]},["fb15_31"]={["dsc"]=[[你走在一条青石大道上，人来人往非常繁忙，不时地有人骑着马匆匆而过。大道两旁有一些小货摊，似乎是一处集市。东面就是苏州城了。西北方通向寒山寺。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_31]],["item1"]=[[4qidraddqi3]],["leftUp"]=[[fb15_32]],["name"]=[[青石官道]],["permission"]=2,["right"]=[[fb15_30]],["role1"]=[[fb15r31_1]],["stepMusic"]=[[jiaobu]]},["fb15_32"]={["dsc"]=[[你走出西门约三十里地，就到了枫桥镇，在唐元和年间，有高僧寒山子曾来此居住，后希迁禅师在此建寺院时，更名寒山寺。唐开元年间，诗人张继赴京应试落第，返途舟船停靠枫桥，赋诗一首:“月落乌啼霜满天，江枫渔火对愁眠，姑苏城外寒山寺，夜半钟声到客船”。从此，诗韵钟声，脍炙人口，寺因诗而名扬天下。]],["id"]=[[fb15_32]],["item1"]=[[lbr32_1]],["item2"]=[[lbr32_2]],["item3"]=[[lbr32_3]],["item4"]=[[fb2085dj]],["name"]=[[寒山寺]],["permission"]=2,["rightDown"]=[[fb15_31]],["role1"]=[[fb15r32_1]],["role2"]=[[fb15r32_2]],["role3"]=[[fb15r32_100]],["role4"]=[[fb15r32_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_74]]},["fb15_33"]={["down"]=[[fb15_73]],["dsc"]=[[寺的北面有一座桥孔呈半圆的单空石桥--枫桥，她跨于运河的枫桥湾。桥的东面是铁岭关，它与白虎关，浒墅关，合称苏州三关。]],["id"]=[[fb15_33]],["item1"]=[[fb15item4]],["item2"]=[[fb15item326]],["name"]=[[枫桥]],["permission"]=2,["role1"]=[[fb15r33_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_34]]},["fb15_34"]={["down"]=[[fb15_33]],["dsc"]=[[关呈长方形，砖石结构，正中的三层敌楼为新建。铁岭关地处水陆要冲登敌楼，既可了望，又能放炮射箭。这关垣、运河、石桥所组成的联合工事，当时是为了防御合抵抗侵扰的倭寇。]],["id"]=[[fb15_34]],["name"]=[[铁岭关]],["permission"]=2,["role1"]=[[fb15r34_1]],["role2"]=[[fb15r34_2]],["stepMusic"]=[[jiaobu]]},["fb15_35"]={["down"]=[[fb15_19]],["dsc"]=[[沧浪亭在苏州的北大街南侧，因为环境相对幽雅，使得男女老少都喜爱在这里闲庭散步。在亭中放眼望去，四周一片碧绿的草坪，亭子翼然于耸翠之中，飞檐凌空琵琶形牌科，布满檐口四周，亭上的额匾和石柱上的楹联使人更加喜爱这里。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_35]],["leftDown"]=[[fb15_20]],["name"]=[[沧浪亭]],["permission"]=1,["rightDown"]=[[fb15_36a]],["role1"]=[[fb15r35_1]],["role2"]=[[fb15r35_2]],["role3"]=[[znq3cd9]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_46]]},["fb15_36"]={["down"]=[[fb15_41]],["dsc"]=[[你走在东大街上，踩着坚实的青石板地面。东边是东大街的延伸，南面是苏州城里一个老字号的当铺，北面是一条小胡同。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_36]],["left"]=[[fb15_36a]],["name"]=[[东大街]],["permission"]=2,["right"]=[[fb15_42]],["role1"]=[[fb15r36_1]],["role2"]=[[fb15r36_2]],["role3"]=[[fb15r36_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_37]]},["fb15_36a"]={["dsc"]=[[你走在东大街上，踩着坚实的青石板地面。东边是东大街的延伸，南面是苏州城里一个老字号的当铺，北面是一条小胡同。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_36a]],["leftDown"]=[[fb15_19]],["leftUp"]=[[fb15_35]],["name"]=[[东大街]],["permission"]=2,["right"]=[[fb15_36]],["role1"]=[[fb15r36a_1]],["role2"]=[[fb15r36a_2]],["stepMusic"]=[[jiaobu]]},["fb15_37"]={["down"]=[[fb15_36]],["dsc"]=[[这是一条黑暗、肮脏的小巷，空气中仿佛飘扬着一股罪恶的气息，东北边通向小巷深处，正人君子当然是不会往那边走去的。往南走就会回到城中大路了。西面是一条小巷，名为“生死巷”。]],["id"]=[[fb15_37]],["left"]=[[fb15_38]],["name"]=[[胡同]],["permission"]=2,["rightUp"]=[[fb15_39]],["role1"]=[[fb15r37_1]],["stepMusic"]=[[jiaobu]]},["fb15_38"]={["dsc"]=[[这里是苏州擂台前面的一个大型广场，有许多人正在擂台上比武，到处是人山人海，如果你也想试试身手，那么就请跳上擂台比试比试吧。]],["fightBackground"]=[[擂台]],["id"]=[[fb15_38]],["name"]=[[擂台]],["permission"]=2,["right"]=[[fb15_37]],["role1"]=[[fb15r38_1]],["role2"]=[[fb15r38_2]],["role3"]=[[fb15r38_3]],["role4"]=[[fb15r38_4]],["stepMusic"]=[[jiaobu]]},["fb15_39"]={["dsc"]=[[这是一条黑暗、肮脏的小巷，空气中仿佛飘扬着一股罪恶的气息，几个贼眉鼠眼地盯着你的腰包，看来会马上扑上来。]],["id"]=[[fb15_39]],["item1"]=[[fb15item316]],["leftDown"]=[[fb15_37]],["name"]=[[胡同]],["permission"]=2,["right"]=[[fb15_40]],["role1"]=[[fb15r39_1]],["stepMusic"]=[[jiaobu]]},["fb15_40"]={["dsc"]=[[这是一条黑暗、肮脏的小巷，空气中仿佛飘扬着一股罪恶的气息，几个流氓在游荡，向东南就能回到大街，你还是赶快走吧。]],["id"]=[[fb15_40]],["item1"]=[[fb15item318]],["left"]=[[fb15_39]],["name"]=[[胡同]],["permission"]=2,["rightDown"]=[[fb15_42]],["rightUp"]=[[fb15_114]],["role1"]=[[fb15r40_1]],["role2"]=[[fb15r40_101]],["role3"]=[[fb15r40_102]],["role4"]=[[fb15r40_103]],["stepMusic"]=[[jiaobu]]},["fb15_41"]={["dsc"]=[[这是一家以买卖公平著称的当铺，一个五尺高的柜台挡在你的面前，柜台上摆着一个牌子，柜台后坐着位老板，一双精明的眼睛上上下下打量着你。]],["id"]=[[fb15_41]],["item1"]=[[fb15item24]],["item2"]=[[fb15item25]],["item3"]=[[fb15item26]],["name"]=[[宝和记]],["permission"]=2,["role1"]=[[fb15r41_1]],["role2"]=[[fb15item21]],["role3"]=[[fb15item22]],["role4"]=[[fb15item23]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_36]]},["fb15_42"]={["down"]=[[fb15_44]],["dsc"]=[[你走在东大街上，踩着坚实的青石板地面。东边是东城门，可以听到守城官兵的吆喝声，北边是一家老字号的药铺，南边是打铁铺，叮叮当当的声音老远就能听到。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_42]],["item1"]=[[fubentiaozhuan4]],["left"]=[[fb15_36]],["leftUp"]=[[fb15_40]],["name"]=[[东大街]],["permission"]=2,["right"]=[[fb15_45]],["rightUp"]=[[fb15_141]],["role1"]=[[fb15r42_1]],["role2"]=[[fb15r42_100]],["role3"]=[[fb15r42_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_43]]},["fb15_43"]={["down"]=[[fb15_42]],["dsc"]=[[这是一家药铺，一股浓浓的药味让你几欲窒息，那是从药柜上的几百个小抽屉里散发出来的。药房先生却不在店内。一名小伙计站在柜台后招呼着顾客。]],["id"]=[[fb15_43]],["name"]=[[立春堂]],["permission"]=2,["role1"]=[[fb15r43_1]],["stepMusic"]=[[jiaobu]]},["fb15_44"]={["dsc"]=[[这是一家简陋的打铁铺，中心一个火炉，炉火忽红忽青，热焰灼人。一位光膀铁匠满头大汗挥舞着铁锤，专心致志地在打铁。墙角堆满了已完工和未完工的铁器等物。]],["id"]=[[fb15_44]],["item1"]=[[duanzaoronglu1]],["name"]=[[打铁铺]],["permission"]=2,["role1"]=[[fb15r44_1]],["role2"]=[[fb15r44_2]],["role3"]=[[fb15r44_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_42]]},["fb15_45"]={["dsc"]=[[这是号称天堂的苏州东城门，城门正上方刻着“东门”两个楷书大字，城墙上贴着几张官府告示。官兵们警惕地注视着过往行人，你最好小心为妙。一条笔直的青石板大道向东西两边延伸，西边是城里。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_45]],["left"]=[[fb15_42]],["name"]=[[东门]],["permission"]=2,["role1"]=[[fb15r45_100]],["role2"]=[[fb15r45_101]],["stepMusic"]=[[jiaobu]]},["fb15_46"]={["down"]=[[fb15_35]],["dsc"]=[[你走在一条繁忙的街道上，看着操着南腔北调的人们行色匆匆，许多人都往南边走去，那里有一个热闹的亭子。西南面是一家戏园子，不时传来叫好声，来自各地的人们进进出出。在东面是一个客店。西面是一个马厩。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_46]],["left"]=[[fb15_47]],["leftDown"]=[[fb15_48]],["name"]=[[北大街]],["permission"]=1,["right"]=[[fb15_49]],["role1"]=[[fb15r46_1]],["role2"]=[[fb15r46_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_52]]},["fb15_47"]={["down"]=[[fb15_48]],["dsc"]=[[这是北大街的马厩，常年供应新鲜草料。苏州民风淳朴，马夫们会把马牵到马厩好生照看，将它们喂饱饮足，再洗刷得干乾净净，一直伺候到客人上路。马厩中堆放著几堆草料，正中有一口泔槽。]],["id"]=[[fb15_47]],["name"]=[[马厩]],["permission"]=2,["right"]=[[fb15_46]],["role1"]=[[fb15r47_1]],["stepMusic"]=[[jiaobu]]},["fb15_48"]={["dsc"]=[[这是一座苏州城里鼎鼎有名的戏园，戏园中生，旦，净，墨，丑一应具全，场中一个大戏台，台上正在唱着《遇长春》，台下不时地传来票友们的叫跃，喝彩声。你也忍不住想坐下来看看戏，放松一下筋骨。]],["id"]=[[fb15_48]],["item1"]=[[fb15item302]],["item2"]=[[cg2item5]],["name"]=[[戏园子]],["permission"]=2,["rightUp"]=[[fb15_46]],["role1"]=[[fb15r48_1]],["role2"]=[[fb15r48_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_47]]},["fb15_49"]={["dsc"]=[[这是一家价钱低廉的客栈，生意非常兴隆。外地游客多选择这里落脚，你可以在这里打听到各地的风土人情。店小二里里外外忙得团团转，接待着南腔北调的客人。]],["id"]=[[fb15_49]],["left"]=[[fb15_46]],["name"]=[[客店]],["permission"]=2,["role1"]=[[fb15r49_1]],["role2"]=[[fb15r49_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_50]]},["fb15_50"]={["down"]=[[fb15_49]],["dsc"]=[[你正走在客店二楼的走廊上，可以听到从客房里不时地呼呼的打酣声，一阵高过一阵。不时有睡意朦胧的旅客进进出出，到楼下的掌柜处付了钱再上来睡觉。]],["id"]=[[fb15_50]],["item1"]=[[fb15item301]],["name"]=[[客店二楼]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_51"]={["dsc"]=[[这是一座苏州城里有名的寺庵，庵中正面是释加摩尼佛眼，似乎在注视前来礼佛之人。右壁一尊诸天用三个手指托起一块轻柔的绣花经盖。左壁的每尊罗汉塑像造型生动，各具特征，到达了以神人话、精神超忽、呼之欲活的艺术境界，令人叹为观止。]],["id"]=[[fb15_51]],["item1"]=[[fb15item9]],["name"]=[[紫金庵]],["permission"]=2,["right"]=[[fb15_52]],["role1"]=[[fb15r51_1]],["role2"]=[[fb15r51_2]],["stepMusic"]=[[jiaobu]]},["fb15_52"]={["down"]=[[fb15_46]],["dsc"]=[[这是一条宽阔的青石街道，向南北两头延伸。北边是北城门通向城外。南边显得很繁忙。东边是一座两层的楼阁，名为春在楼。西面是一座庙庵，南面是一条笔直的大街，十分繁华。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_52]],["item1"]=[[fb15fyb]],["item2"]=[[znqrwdj12]],["item3"]=[[wldhpd]],["left"]=[[fb15_51]],["name"]=[[北大街]],["permission"]=1,["right"]=[[fb15_53]],["role1"]=[[fb15r52_1]],["role2"]=[[fb15r52_100]],["role3"]=[[fb15item327]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_54]]},["fb15_53"]={["dsc"]=[[这是一座苏州城里有名的酒楼，整个楼面以雕刻为特色，砖雕，木雕，石雕。走进楼内，一眼便看到一副八仙上寿图，八仙人被描画的惟妙惟肖。楼内许多南北来往的门客正在聊天品茶，只见店小二忙的不亦乐乎。]],["id"]=[[fb15_53]],["item1"]=[[fb15item300]],["item2"]=[[addbaituo]],["left"]=[[fb15_52]],["name"]=[[春在楼]],["permission"]=2,["role1"]=[[fb15r53_1]],["role2"]=[[fb15r53_104]],["role3"]=[[fb15r53_105]],["role4"]=[[fb15r53_106]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_136]]},["fb15_54"]={["down"]=[[fb15_52]],["dsc"]=[[这是苏州府的北城门。出门远远可见西面的虎丘山。放眼望去尽是绿的田，翠的草和清清的小河。门边官兵身后贴着一份告示。南北一条笔直的官道。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_54]],["item1"]=[[fubentiaozhuan1]],["left"]=[[fb15_76]],["name"]=[[北门]],["permission"]=1,["rightUp"]=[[fb15_138]],["role1"]=[[fb15r54_1]],["role2"]=[[fb15r54_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_55]]},["fb15_55"]={["down"]=[[fb15_54]],["dsc"]=[[你走在一条青石大道上，人来人往非常繁忙，不时地有人骑着马匆匆而过。大道两旁有一些小货摊，似乎是一处集市。南面就是苏州城了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_55]],["leftDown"]=[[fb15_56]],["name"]=[[青石官道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb15_84]]},["fb15_56"]={["down"]=[[fb15_57]],["dsc"]=[[虎丘山因其山形似蹲虎而得名。又相传吴王葬后，有白虎出现其墓上，故名虎丘。山前绝岩幽谷，花木繁茂，景色绮丽，后山空蒙宽广，石壁树立，气势雄浑。有“山藏寺里”的特色，被誉为“吴中第一名胜”。]],["id"]=[[fb15_56]],["name"]=[[虎丘山]],["permission"]=2,["rightUp"]=[[fb15_55]],["role1"]=[[fb15r56_1]],["stepMusic"]=[[jiaobu]]},["fb15_57"]={["dsc"]=[[头山门在虎丘山的南面，形似虎头。隔河照墙上书着“海涌流辉”四个大字，以示虎丘与大海的渊源关系。]],["id"]=[[fb15_57]],["left"]=[[fb15_58]],["name"]=[[头门山]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb15_56]]},["fb15_58"]={["dsc"]=[[在虎丘山东面就是万景山庄，是一个较大的盆景园，有盆名为“秦汉遗韵”的圆柏，树龄已逾五百年，被誉为“盆景之王”。园内景色优美，颇富园林雅趣。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb15_58]],["left"]=[[fb15_60]],["name"]=[[万景山庄]],["permission"]=2,["right"]=[[fb15_57]],["rightUp"]=[[fb15_59]],["role1"]=[[fb15r58_1]],["role2"]=[[fb15r58_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_68]]},["fb15_59"]={["dsc"]=[[在山道西侧有一憨憨泉，系南朝梁代高僧憨憨尊者所开凿，距今一千四百多年。据说泉眼通海，姑又名“海涌泉”。水甚清冽为“天下第五泉”。石刻“憨憨泉”三字，系北宋吕升卿所题。]],["id"]=[[fb15_59]],["leftDown"]=[[fb15_58]],["name"]=[[憨憨泉]],["permission"]=2,["role1"]=[[fb15r59_1]],["role2"]=[[fb15r59_2]],["stepMusic"]=[[jiaobu]]},["fb15_60"]={["down"]=[[fb15_65]],["dsc"]=[[在山道东侧是试剑石，呈椭圆形，正中有条深而齐裂的裂缝，相传吴王得“干将”，“莫邪”剑后，为试其锋利，将石劈开。石旁刻着元代顾瑛的诗句“剑试一痕秋，崖倾水断流，如何百年后，不斩赵高头？”的诗句。]],["id"]=[[fb15_60]],["item1"]=[[bfitem3]],["name"]=[[试剑石]],["permission"]=2,["right"]=[[fb15_58]],["rightUp"]=[[fb15_61]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_63]]},["fb15_61"]={["dsc"]=[[在试剑石北面就是古真娘墓，真娘也称贞娘，因安史之乱流落江南，受骗流落堕入青楼。贞娘为守贞操，自尽抗之。后人筑亭其上，墓前石刻“香魂”两字，墓上遍栽花卉。唐代白居易等诗人墨客纷纷为之题诗，褒赞真娘之贞烈。]],["id"]=[[fb15_61]],["leftDown"]=[[fb15_60]],["name"]=[[真娘墓]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb15_62]]},["fb15_62"]={["down"]=[[fb15_61]],["dsc"]=[[在真娘幕后的土丘上，有一座小亭子，名为孙武亭。相传春秋时，兵家孙武曾在此训练两队宫女，由吴王的两个宠姬分别担任队长，由于宠姬与宫女们不听军令，虽三令五申，仍置若罔闻，孙武遂下令，先斩两姬于军前以整军纪。后人遂筑此亭。]],["id"]=[[fb15_62]],["item1"]=[[fb15item16]],["name"]=[[孙武亭]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_63"]={["down"]=[[fb15_60]],["dsc"]=[[在山半腰有一块巨石，因石形如枕而得名枕石。相传东晋高僧，常在此倚石阅经，倦则枕石休息。此石其形又象蜒蚰，故亦称“蜒蚰石”。另因有“唐寅三笑姻缘”的传说，故又名“鸳鸯石”。这块大石，实系海涌山遗物。]],["id"]=[[fb15_63]],["name"]=[[枕石]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb15_64"]={["dsc"]=[[在千人石西面就是致爽阁，又名伏虎阁，在虎丘塔的西南面，是山上的最高点。阁名取“四山爽气，日夕西来”之意。旧称“小五台”，是海涌峰顶。阁外平台宽阔，俯瞰沃野；远眺群峰逶迤，可赏著名上午“狮子回头看虎丘”一景。深秋季节观成群飞翔的苍鹰，蔚为壮观。]],["id"]=[[fb15_64]],["name"]=[[致爽阁]],["permission"]=2,["rightDown"]=[[fb15_65]],["role1"]=[[fb15r64_1]],["stepMusic"]=[[jiaobu]]},["fb15_65"]={["dsc"]=[[在虎丘山中心，有一块千人石，巨石呈暗紫红色，由南向北倾斜石面甚平坦，石壁如斧削。传说吴王墓筑成后，其子夫差怕泄露筑墓秘密假借墓成祝酒观舞之名，将千余名工匠全部杀戮，鲜血渗透石中，成暗红色。]],["id"]=[[fb15_65]],["leftUp"]=[[fb15_64]],["name"]=[[千人石]],["permission"]=2,["right"]=[[fb15_66]],["role1"]=[[fb15r65_1]],["role2"]=[[fb15r65_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_60]]},["fb15_66"]={["dsc"]=[[二仙亭在千人石东侧，建于北宋。亭壁嵌两方石碑，分别刻着五代宋初陈抟与唐代吕洞宾二仙像。亭柱上有两幅石刻楹联:“梦中说梦原非梦，元里求元便是元”；“昔日岳阳曾显迹，今朝虎阜再留踪”。]],["id"]=[[fb15_66]],["left"]=[[fb15_65]],["name"]=[[二仙亭]],["permission"]=2,["role1"]=[[fb15r66_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_67]]},["fb15_67"]={["down"]=[[fb15_66]],["dsc"]=[[白莲池位于二仙亭的北面，池中种有千叶莲花，池上架彩莲曲桥，相传吴王夫差与西施曾在此采莲赏荷。]],["id"]=[[fb15_67]],["name"]=[[白莲池]],["permission"]=2,["role1"]=[[fb15r67_1]],["stepMusic"]=[[jiaobu]]},["fb15_68"]={["down"]=[[fb15_58]],["dsc"]=[[一座富丽堂皇的大宅院出现在你的眼前，两头高大的石狮子镇住了大门两侧，大门上的朱漆足足有三寸厚。门上一张匾，上书“翰林府”三个大字。]],["id"]=[[fb15_68]],["name"]=[[翰林府门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb15_69]]},["fb15_69"]={["down"]=[[fb15_68]],["dsc"]=[[你走进大院，迎面是一个假山水池，池上摆着一块奇形怪状的石头，据说是当年花石纲的遗石。水池的两旁种满了花草。东边是一棵槐树，郁郁葱葱，遮盖了大半个院子，显得阴森恐怖。一条长廊走道通往后院，有几个家丁把守。]],["id"]=[[fb15_69]],["name"]=[[翰林府院]],["permission"]=2,["role1"]=[[fb15r69_1]],["role2"]=[[fb15r69_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_70]]},["fb15_70"]={["down"]=[[fb15_69]],["dsc"]=[[这里是翰林府的后院。院子里种了不少的各种奇花异草，尤以各色菊花为多。北面有一扇门。]],["id"]=[[fb15_70]],["name"]=[[后院]],["permission"]=2,["role1"]=[[fb15r70_1]],["role2"]=[[fb15r70_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_71]]},["fb15_71"]={["down"]=[[fb15_70]],["dsc"]=[[这是凌小姐的闺房，一股幽香扑面而来。一张绣榻放在墙角，垂着细纱。西面是座花园。]],["id"]=[[fb15_71]],["left"]=[[fb15_72]],["name"]=[[闺房]],["permission"]=2,["role1"]=[[fb15r71_1]],["role2"]=[[fb15r71_100]],["role3"]=[[fb15r71_101]],["stepMusic"]=[[jiaobu]]},["fb15_72"]={["dsc"]=[[这里是翰林府的花园。院子里种了各色名贵的菊花。黄菊有都胜、金芍药、报君知。白菊有月下白、一团雪、貂蝉拜月。紫菊有双飞燕、紫玉莲、玛瑙盘。红菊有美人红、醉贵妃、绣芙蓉…院中有几盆颜色特别娇艳的黄花，花瓣黄得像金子一样，花朵的样子很像荷花。那就是从天竺传来的金波旬花。]],["id"]=[[fb15_72]],["item1"]=[[fb15item14]],["item2"]=[[fb15item15]],["name"]=[[花园]],["permission"]=2,["right"]=[[fb15_71]],["role1"]=[[fb15r72_1]],["role2"]=[[fb15item11]],["role3"]=[[fb15item12]],["role4"]=[[fb15item13]],["stepMusic"]=[[jiaobu]]},["fb15_73"]={["dsc"]=[[这里供奉着相传为“和合二仙”化身的寒山，拾得金身塑像，形态生动，逗人喜爱。寒山寺每年除夕半夜，撞钟一百零八响，其含义是除旧迎新和纪念佛门一百零八位高僧。]],["id"]=[[fb15_73]],["item1"]=[[fb15item9]],["item2"]=[[4qidraddqi4]],["left"]=[[fb15_74]],["name"]=[[寒拾殿]],["permission"]=2,["role1"]=[[fb15r73_1]],["role2"]=[[fb15r73_2]],["role3"]=[[fb15r73_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_33]]},["fb15_74"]={["down"]=[[fb15_32]],["dsc"]=[[一走进正殿，首先你看到的是号称扬州八怪的画家罗聘所绘寒山，拾得写意画像石刻和郑文焯指画丰干和尚石刻像。左右碑廊中藏历历代名人岳飞等题写得诗文，楹联碑刻树方，世传精品。正殿左右的偏殿保存着宋代樟木雕塑的金身五百罗汉。]],["id"]=[[fb15_74]],["item1"]=[[fb15item8]],["item2"]=[[fb15item9]],["name"]=[[正殿]],["permission"]=2,["right"]=[[fb15_73]],["role1"]=[[fb15r74_1]],["role2"]=[[fb15r74_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_137]]},["fb15_75"]={["dsc"]=[[这里是监狱，约莫两丈见方的一间大石室，墙壁和顶板都是大石所砌。墙角里放着一只粪桶，鼻中闻到的尽是臭气和霉气。从西面墙上的小窗望去，可以见到翰林府的一角。]],["id"]=[[fb15_75]],["name"]=[[监狱]],["permission"]=2,["right"]=[[fb15_76]],["stepMusic"]=[[jiaobu]]},["fb15_76"]={["dsc"]=[[这里是兵营，密密麻麻到处都是官兵，有的在武将的指挥下列队操练，有的独自在练功，有的坐着、躺着正在休息。南墙下坐着主帅，不动声色地寻视着四周。]],["id"]=[[fb15_76]],["left"]=[[fb15_75]],["name"]=[[兵营]],["permission"]=2,["right"]=[[fb15_54]],["role1"]=[[fb15r76_1]],["role2"]=[[fb15r76_3]],["stepMusic"]=[[jiaobu]]},["fb15_77"]={["dsc"]=[[这里是嘉兴南湖水下，四周倒还比较明亮，几道天光从头顶的潭水中投射下来，显得十分美丽。脚下漆黑一片也不知有些什么。]],["id"]=[[fb15_77]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_78]],["role1"]=[[fb15item20]],["stepMusic"]=[[jiaobu]]},["fb15_78"]={["dsc"]=[[这里是嘉兴南湖水下，四周倒还渐渐有些昏暗了，几道天光从头顶的潭水中投射下来，此时也不那么瑰丽了，昏沉沉的犹如天边的晚霞。脚下漆黑一片也不知有些什么。四周的水流也没有那么平静了，似乎在向一个方向流动着。你不由心中一动:不会有暗流吧！！]],["id"]=[[fb15_78]],["left"]=[[fb15_77]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_79]],["role1"]=[[fb15r79_1]],["role2"]=[[fb15r79_2]],["stepMusic"]=[[jiaobu]]},["fb15_79"]={["dsc"]=[[这里是嘉兴南湖底，四周黑忽忽的，头顶上只能看见一点亮光，身边的水流似乎更加湍急了。脚下似乎有一点亮光，也不知是些什么。周围一片死寂，似乎暗藏着层层杀机。]],["id"]=[[fb15_79]],["left"]=[[fb15_78]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_80]],["stepMusic"]=[[jiaobu]]},["fb15_80"]={["dsc"]=[[这里是嘉兴南湖底，四周黑忽忽的，头顶上只能看见一点亮光，身边的水流似乎更加湍急了。脚下似乎有一点亮光，也不知是些什么。周围一片死寂，似乎暗藏着层层杀机。]],["id"]=[[fb15_80]],["left"]=[[fb15_79]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_81]],["role1"]=[[fb15r81_1]],["role2"]=[[fb15r81_2]],["stepMusic"]=[[jiaobu]]},["fb15_81"]={["dsc"]=[[这里是嘉兴南湖底，四周黑忽忽的，头顶上只能看见一点亮光，身边的水流似乎更加湍急了。脚下似乎有一点亮光，也不知是些什么。周围一片死寂，似乎暗藏着层层杀机。]],["id"]=[[fb15_81]],["left"]=[[fb15_80]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_82]],["stepMusic"]=[[jiaobu]]},["fb15_82"]={["dsc"]=[[这里是嘉兴南湖底，四周黑忽忽的，头顶上看不见一点亮光，身边的水流忽上忽下的涌动着。看起来是一处海眼。东边似乎有一点亮光，被一块巨大的石块挡着。周围一片死寂，似乎暗藏着层层杀机。]],["id"]=[[fb15_82]],["left"]=[[fb15_81]],["name"]=[[嘉兴南湖]],["permission"]=2,["right"]=[[fb15_83]],["stepMusic"]=[[jiaobu]]},["fb15_83"]={["dsc"]=[[这里是潭中的一个小洞，里面零零落落的有几块石头。]],["id"]=[[fb15_83]],["left"]=[[fb15_82]],["name"]=[[湖心小洞]],["permission"]=2,["role1"]=[[fb15item19]],["stepMusic"]=[[jiaobu]]},["fb15_84"]={["down"]=[[fb15_55]],["dsc"]=[[这里是一片青草地，青草长势茂盛，在往北就是苏州郊外了。]],["id"]=[[fb15_84]],["name"]=[[青草地]],["permission"]=2,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_85]]},["fb15_85"]={["down"]=[[fb15_84]],["dsc"]=[[这里是苏州郊外，很多人聚集在这里放风筝，再往前就是白云山了，那儿可是踏青的好去处。]],["id"]=[[fb15_85]],["item1"]=[[fb15r85_100]],["name"]=[[郊外]],["permission"]=2,["role1"]=[[fb15r85_1]],["role2"]=[[fb15r85_2]],["role3"]=[[fb15r85_3]],["role4"]=[[fb15r85_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb15_86]]},["fb15_86"]={["down"]=[[fb15_85]],["dsc"]=[[白云山向以“红枫、奇石、清泉”三绝著称，有万笏朝天、高义叠翠、万丈红霞、玉泉轻吟等十八处胜景，乃是苏州踏青，春游的不二之选。]],["id"]=[[fb15_86]],["item1"]=[[cg2item4]],["name"]=[[白云山]],["permission"]=2,["role1"]=[[fb15r86_1]],["role2"]=[[fb15r86_2]],["role3"]=[[fb15r86_100]],["stepMusic"]=[[jiaobu]]},["fb15_87"]={["down"]=[[fb15_89]],["dsc"]=[[这个房间窗户都被木条封死了，光线十分暗淡。四周散落着一些发黑的破布，依稀可以看清一些布娃娃的头。一张不大的床靠墙放着，已经烂的只剩一块床板。窗户下面放着一个铁皮箱子，一把锈迹斑斑的大锁锁在上面。]],["id"]=[[fb15_87]],["item1"]=[[fb15item73]],["item2"]=[[21zyitem05]],["name"]=[[暗房]],["permission"]=2,["role1"]=[[fb15item206]],["role2"]=[[fb15item27]],["role3"]=[[fb15item39]],["role4"]=[[fb15item72]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_88"]={["down"]=[[fb15_90]],["dsc"]=[[干涸的池塘，池塘底的污泥还有一些水分，正在不断地冒着泡，空气中弥漫着一阵腥臭。]],["id"]=[[fb15_88]],["name"]=[[枯水池]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_89"]={["dsc"]=[[房间中有一张大床，一个书桌，都已经腐烂的不成样子。桌子上放着一个铜镜，将房间的景物映照其中。墙上挂着一幅山水画，上面落满了灰尘。地上的灰尘中，一排小脚印通向更里面的暗房。]],["id"]=[[fb15_89]],["item1"]=[[fb15item63]],["item2"]=[[cg2item4]],["item3"]=[[21zyitem01]],["name"]=[[卧室]],["permission"]=2,["right"]=[[fb15_90]],["role1"]=[[fb15item205]],["role2"]=[[fb15item28]],["role3"]=[[fb15item29]],["role4"]=[[fb15item62]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_87]]},["fb15_90"]={["down"]=[[fb15_93]],["dsc"]=[[一个废弃的庭院，已经很久没有人打理，花都已经枯死了。摔碎的花盆陶片到处都是，一不小心就会割伤。]],["id"]=[[fb15_90]],["item1"]=[[fb15item30]],["left"]=[[fb15_89]],["name"]=[[荒院]],["permission"]=2,["right"]=[[fb15_91]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_88]]},["fb15_91"]={["dsc"]=[[一张屏风挡在门口，上面布满了蛛网。再往里面是一个洗澡用的木桶，桶里面是黑色的液体，泡着什么东西，散发出恶臭。桶的周围很湿，桶身上有一个手掌样的水痕，还没有散去。]],["id"]=[[fb15_91]],["item1"]=[[fb15item31]],["left"]=[[fb15_90]],["name"]=[[浣洗室]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_92"]={["dsc"]=[[大厅旁边的一个小厅，房间里面空荡荡的，窗户的破洞中吹进来阵阵冷风。]],["id"]=[[fb15_92]],["item1"]=[[fb15item32]],["name"]=[[偏厅]],["permission"]=2,["right"]=[[fb15_93]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_93"]={["down"]=[[fb15_97]],["dsc"]=[[宽敞的大厅，整齐的放着两排椅子。空无一物的椅子上传来一阵不寒而栗的感觉，仿佛有人在窥视。大厅的梁柱上画着十分精美的彩绘，已经剥落了不少。]],["id"]=[[fb15_93]],["item1"]=[[fb15item33]],["left"]=[[fb15_92]],["name"]=[[阴暗正厅]],["permission"]=2,["right"]=[[fb15_94]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_90]]},["fb15_94"]={["dsc"]=[[这个房间里面摆着巨大的长桌，餐具胡乱摆在桌子上。一些碗里还有采育的食物，已经腐烂的看不出是什么，爬着一些细细的蛆虫。]],["id"]=[[fb15_94]],["item1"]=[[fb15item34]],["left"]=[[fb15_93]],["name"]=[[饭厅]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_95"]={["down"]=[[fb15_99]],["dsc"]=[[一个十分潮湿的房间，墙角湿气很重。放着一些米缸和杂物工具，一些米缸破开大口，里面没有东西。一些完整的米缸里面传来轻微的响声。]],["id"]=[[fb15_95]],["item1"]=[[fb15item38]],["item2"]=[[fb15item64]],["item3"]=[[fb15item204]],["item4"]=[[21zyitem03]],["name"]=[[发潮房间]],["permission"]=2,["role1"]=[[fb15item56]],["role2"]=[[fb15item57]],["role3"]=[[fb15item35]],["role4"]=[[fb15item36]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_96"]={["dsc"]=[[这个灵堂只放着一具小棺材。棺材由铁铸成，十分沉重，上面枷着手臂粗的锁链。棺材前面点着两个长明灯，还在微弱地燃烧着，发出莹莹绿光。]],["id"]=[[fb15_96]],["item1"]=[[fb15item40]],["item2"]=[[fb15item84]],["name"]=[[灵堂]],["permission"]=2,["right"]=[[fb15_97]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_97"]={["down"]=[[fb15_101]],["dsc"]=[[走进房间便看到一排棺材整齐的摆放着，仔细一数，一共有七具，棺材上落满了灰尘，一只棺材一角被打开了，里面空空如也。棺材前面点着两个长明灯，还在微弱地燃烧着，发出莹莹绿光。]],["id"]=[[fb15_97]],["item1"]=[[fb15item41]],["item2"]=[[fb15item42]],["left"]=[[fb15_96]],["name"]=[[灵堂]],["permission"]=2,["right"]=[[fb15_98]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_93]]},["fb15_98"]={["dsc"]=[[这里似乎是一个囚室，角落里有一个牢笼，门已经被打开。一些刑具散放在牢笼旁，地上满是黑色的污垢。]],["id"]=[[fb15_98]],["item1"]=[[fb15item43]],["item2"]=[[fb15item82]],["left"]=[[fb15_97]],["name"]=[[囚室]],["permission"]=2,["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]]},["fb15_99"]={["dsc"]=[[幽长潮湿的走廊。木质的地板被湿气侵蚀，腐朽得十分厉害，踩上去咯吱作响，在空旷的走廊中传来阵阵回音。]],["id"]=[[fb15_99]],["name"]=[[潮湿走廊]],["permission"]=2,["right"]=[[fb15_100]],["roomBgm"]=[[mengjing]],["stepMusic"]=[[mudiban]],["up"]=[[fb15_95]]}}0000000000000000